-- Contrôle AVANT (attendu, hors « rendez-vous » : salaire 62, living 57, fiscalite 53, se 50, arnaques 49, demenager 48, assurance 46, dossier 42)
-- (impératifs -ez attendus avant : salaire 24, living 53, fiscalité 14, réseau 27, arnaques 52, déménager 38, assurance 25, dossier 32 ; dry-run du 03/09 : 0 partout après)
select slug, (select count(*) from regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '\m(vous|votre|vos)\M', 'gi')) as vous, (select count(*) from regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '(?:^|[\s*>#-])((?:[A-ZÉ][a-zé]+|[a-zé]+)ez)\M', 'g') as m where lower(m[1]) not in ('chez','assez','rez','nez')) as ez from blog_posts where slug in ('salaire-suisse-net-frontalier-2026','living-in-france-working-in-geneva','fiscalite-frontalier-geneve-impots-2026','se-faire-reseau-geneve-arriver-seul','arnaques-logement-frontalier-geneve-eviter','demenager-geneve-frontalier-checklist','assurance-sante-frontalier-lamal-cmu-budget','dossier-location-frontalier-suisse-france') order by slug;

