-- Contrôle APRÈS « vous » (attendu : 0 partout en vous_hors_url ; vous_brut = 1 pour assurance-sante = l'URL gouv.fr)
select slug, (select count(*) from regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '\m(vous|votre|vos)\M', 'gi')) as vous_brut, (select count(*) from regexp_matches(regexp_replace(regexp_replace(content_fr, '\]\([^)]*\)', ']', 'g'), 'rendez-vous', '', 'gi'), '\m(vous|votre|vos)\M', 'gi')) as vous_hors_url from blog_posts where slug in ('salaire-suisse-net-frontalier-2026','living-in-france-working-in-geneva','fiscalite-frontalier-geneve-impots-2026','se-faire-reseau-geneve-arriver-seul','arnaques-logement-frontalier-geneve-eviter','demenager-geneve-frontalier-checklist','assurance-sante-frontalier-lamal-cmu-budget','dossier-location-frontalier-suisse-france') order by slug;

-- Contrôle APRÈS des impératifs de vouvoiement restants (verbes en -ez, « rendez-vous » neutralisé) : attendu 0 ligne
select slug, m[1] as mot from blog_posts, regexp_matches(regexp_replace(content_fr, 'rendez-vous', '', 'gi'), '(?:^|[\s*>#-])((?:[A-ZÉ][a-zé]+|[a-zé]+)ez)\M', 'g') as m where slug in ('salaire-suisse-net-frontalier-2026','living-in-france-working-in-geneva','fiscalite-frontalier-geneve-impots-2026','se-faire-reseau-geneve-arriver-seul','arnaques-logement-frontalier-geneve-eviter','demenager-geneve-frontalier-checklist','assurance-sante-frontalier-lamal-cmu-budget','dossier-location-frontalier-suisse-france') and lower(m[1]) not in ('chez','assez','rez','nez') order by 1, 2;
